package com.fixmer.mared.technology.workspace;
import com.fixmer.mared.Mared;import com.fixmer.genesis.technology.workspace.*;
import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.level.storage.LevelResource;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.server.*;import net.neoforged.neoforge.network.PacketDistributor;
import java.nio.file.Path;import java.util.*;import java.util.concurrent.*;
/** Disk I/O stays off the game thread; actual session and creation permission are checked on the server thread. */
@EventBusSubscriber(modid=Mared.MOD_ID)
public final class WorkspaceServer112 {
 private WorkspaceServer112(){}private static final Map<MinecraftServer,Actor> actors=new IdentityHashMap<>();
 private static final class Actor{final Path directory;final ThreadPoolExecutor io=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(32),r->{var t=new Thread(r,"Genesis-workspace112");t.setDaemon(true);return t;});final Set<UUID> pending=new HashSet<>();final Map<UUID,WorkspaceRate112> last=new HashMap<>();WorkspaceStore112 store;volatile boolean stopped;Actor(Path directory){this.directory=directory;}}
 @SubscribeEvent public static void started(ServerStartedEvent e){var s=e.getServer();actors.put(s,new Actor(s.getWorldPath(LevelResource.ROOT).resolve("genesis/workspaces112")));}
 private static boolean canCreate(ServerPlayer p,MinecraftServer s){return com.fixmer.mared.technology.permissions.MaopServer113.allowed(p,"WORKSPACE_CREATE");}
 private static boolean current(ServerPlayer p,MinecraftServer s){return p.getServer()==s&&s.getPlayerList().getPlayer(p.getUUID())==p;}
 private static void reply(ServerPlayer p,UUID id,Map<String,String> value){try{var d=new TreeMap<>(value);d.put("request",id.toString());PacketDistributor.sendToPlayer(p,new WorkspacePayloads112.Response(WorkspaceWire112.encode(d)));}catch(Exception bad){Mared.LOGGER.warn("[Workspace112] Cannot encode reply",bad);}}
 public static void receive(ServerPlayer p,byte[] bytes){var s=p.getServer();if(s!=null)s.execute(()->accept(p,s,bytes));}
 private static void accept(ServerPlayer p,MinecraftServer s,byte[] bytes){
  if(!current(p,s)||!p.connection.hasChannel(WorkspacePayloads112.Response.TYPE.id()))return;WorkspaceWire112.Request q;try{q=WorkspaceWire112.request(bytes);}catch(Exception bad){return;}
  Actor a=actors.get(s);if(a==null||a.stopped){reply(p,q.request(),Map.of("result","UNAVAILABLE"));return;}UUID actor=p.getUUID();long now=System.nanoTime();if(a.pending.contains(actor)||!a.last.computeIfAbsent(actor,id->new WorkspaceRate112()).take(now)){reply(p,q.request(),Map.of("result","BUSY"));return;}
  if(a.last.size()>1024)a.last.clear();a.pending.add(actor);boolean create=canCreate(p,s);
  try{a.io.execute(()->{Map<String,String> result;try{CompletableFuture<Boolean> valid=new CompletableFuture<>();s.execute(()->valid.complete(!a.stopped&&actors.get(s)==a&&current(p,s)&&(!create||canCreate(p,s))));if(!valid.get(3,TimeUnit.SECONDS))throw new java.io.IOException("DENIED");if(a.store==null)a.store=new WorkspaceStore112(a.directory);result=a.store.execute(actor,create,q);}catch(Exception bad){String code=bad.getMessage();if(code==null||!Set.of("MIGRATED","DENIED","CONFLICT","NOT_FOUND","LIMIT","INVALID","INVALID_PATH","EXISTS","REQUEST_REUSED","LOCKED","CORRUPT","LINK").contains(code)){Mared.LOGGER.warn("[Workspace112] Operation failed: {}",q.operation(),bad);code="IO_ERROR";}result=Map.of("result",code);}Map<String,String> answer=result;s.execute(()->{a.pending.remove(actor);if(!a.stopped&&actors.get(s)==a&&current(p,s))reply(p,q.request(),players(s,answer));});});}catch(RejectedExecutionException busy){a.pending.remove(actor);reply(p,q.request(),Map.of("result","BUSY"));}
 }
 private static Map<String,String> players(MinecraftServer s,Map<String,String> data){if(!data.containsKey("members"))return data;var out=new TreeMap<>(data);var rows=new StringBuilder();int count=0;for(ServerPlayer p:s.getPlayerList().getPlayers()){if(count++>=16)break;String name=p.getName().getString();if(name.matches("[A-Za-z0-9_]{1,16}"))rows.append(p.getUUID()).append('|').append(name).append('\n');}out.put("players",rows.toString());try{if(WorkspaceWire112.encode(out).length>WorkspaceWire112.MAX_PACKET-80)return data;return out;}catch(Exception bad){return data;}}
 public static CompletableFuture<WorkspaceStore112.Export122> freeze122(ServerPlayer player,MinecraftServer server,UUID project){var result=new CompletableFuture<WorkspaceStore112.Export122>();server.execute(()->{Actor a=actors.get(server);if(a==null||a.stopped||!current(player,server)){result.completeExceptionally(new java.io.IOException("DENIED"));return;}try{a.io.execute(()->{try{if(a.stopped)throw new java.io.IOException("DENIED");if(a.store==null)a.store=new WorkspaceStore112(a.directory);result.complete(a.store.freeze122(player.getUUID(),project));}catch(Exception e){result.completeExceptionally(e);}});}catch(RejectedExecutionException e){result.completeExceptionally(e);}});return result;}
 @SubscribeEvent public static void stopped(ServerStoppedEvent e){Actor a=actors.remove(e.getServer());if(a==null)return;a.stopped=true;try{a.io.getQueue().clear();a.io.execute(()->{if(a.store!=null)try{a.store.close();}catch(Exception bad){Mared.LOGGER.warn("[Workspace112] Close failed",bad);}});}finally{a.io.shutdown();}}
}
